R=C=20
grid=[[0]*20 for _ in range(20)]
markers=[(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)]
for r,c in markers: grid[r][c]=1
for r in range(2,9):
    for c in range(9,16): grid[r][c]=2
# extend horizontal rays outward from each rectangle row only if no marker blocks that side
for r in range(2,9):
    if not any((r,c) in markers for c in range(0,9)):
        for c in range(0,9): grid[r][c]=2
    if not any((r,c) in markers for c in range(16,20)):
        for c in range(16,20): grid[r][c]=2
# extend vertical rays outward from each rectangle col
for c in range(9,16):
    if not any((r,c) in markers for r in range(0,2)):
        for r in range(0,2): grid[r][c]=2
    if not any((r,c) in markers for r in range(9,20)):
        for r in range(9,20): grid[r][c]=2
for row in grid: print(' '.join(map(str,row)))
